def cmp_semver(a, b):
    def parse(v):
        v = v.split('+')[0]
        if '-' in v:
            core, pre = v.split('-', 1)
        else:
            core, pre = v, None
        parts = core.split('.')
        return int(parts[0]), int(parts[1]), int(parts[2]), pre

    def cmp_pre(pa, pb):
        if pa is None and pb is None:
            return 0
        if pa is None:
            return 1
        if pb is None:
            return -1
        ia = pa.split('.')
        ib = pb.split('.')
        for x, y in zip(ia, ib):
            xn, yn = x.isdigit(), y.isdigit()
            if xn and yn:
                xi, yi = int(x), int(y)
                if xi != yi:
                    return -1 if xi < yi else 1
            elif xn:
                return -1
            elif yn:
                return 1
            else:
                if x != y:
                    return -1 if x < y else 1
        if len(ia) != len(ib):
            return -1 if len(ia) < len(ib) else 1
        return 0

    ma, mi, pa, pre_a = parse(a)
    mb, mi_b, pb, pre_b = parse(b)

    if ma != mb:
        return -1 if ma < mb else 1
    if mi != mi_b:
        return -1 if mi < mi_b else 1
    if pa != pb:
        return -1 if pa < pb else 1
    return cmp_pre(pre_a, pre_b)
```

