import re

def gitignore_match(pattern, path):
    dir_only = pattern.endswith('/')
    if dir_only:
        pattern = pattern[:-1]

    anchored = False
    if pattern.startswith('/'):
        anchored = True
        pattern = pattern[1:]

    if pattern == '**':
        regex = '.*'
    elif pattern.startswith('**/'):
        regex = _pattern_to_regex(pattern)
    elif '/' in pattern:
        anchored = True
        regex = _pattern_to_regex(pattern)
    else:
        pattern = '**/' + pattern
        regex = _pattern_to_regex(pattern)

    if dir_only:
        if not path.endswith('/'):
            return False
        path = path[:-1]
    else:
        regex += '/?'
        if path.endswith('/'):
            path = path[:-1]

    return re.fullmatch(regex, path) is not None


def _pattern_to_regex(pattern):
    i = 0
    regex = ''
    n = len(pattern)
    while i < n:
        c = pattern[i]
        if c == '/':
            if i + 2 < n and pattern[i + 1] == '*' and pattern[i + 2] == '*':
                if i + 3 == n:
                    regex += '/.*'
                    i += 3
                elif i + 3 < n and pattern[i + 3] == '/':
                    regex += '/([^/]+/)*'
                    i += 4
                else:
                    regex += '/'
                    i += 1
            else:
                regex += '/'
                i += 1
        elif c == '*':
            if i + 1 < n and pattern[i + 1] == '*':
                if i == 0 and i + 2 < n and pattern[i + 2] == '/':
                    regex += '([^/]+/)*'
                    i += 3
                elif i == 0 and i + 2 == n:
                    regex += '.*'
                    i += 2
                else:
                    regex += '[^/]*'
                    i += 2
            else:
                regex += '[^/]*'
                i += 1
        elif c == '?':
            regex += '[^/]'
            i += 1
        elif c == '[':
            j = i + 1
            if j < n and pattern[j] == '!':
                j += 1
            if j < n and pattern[j] == ']':
                j += 1
            while j < n and pattern[j] != ']':
                j += 1
            if j < n:
                cls = pattern[i:j + 1]
                if len(cls) > 1 and cls[1] == '!':
                    cls = '[^' + cls[2:]
                regex += cls
                i = j + 1
            else:
                regex += re.escape('[')
                i += 1
        else:
            regex += re.escape(c)
            i += 1
    return regex
