def parse_range(header, size):
    if not header or not header.startswith("bytes="):
        return None

    range_spec = header[6:]
    if not range_spec.strip():
        return None

    parts = range_spec.split(",")
    results = []

    for part in parts:
        part = part.strip()
        if "-" not in part:
            return None

        start_str, end_str = part.split("-", 1)

        if start_str == "" and end_str == "":
            return None

        if start_str == "":
            # suffix range: -N
            try:
                suffix_len = int(end_str)
            except ValueError:
                return None
            if suffix_len <= 0:
                continue
            start = max(0, size - suffix_len)
            end = size - 1
            results.append((start, end))
        elif end_str == "":
            # open-ended: N-
            try:
                start = int(start_str)
            except ValueError:
                return None
            if start < 0 or start >= size:
                continue
            end = size - 1
            results.append((start, end))
        else:
            # explicit: N-M
            try:
                start = int(start_str)
                end = int(end_str)
            except ValueError:
                return None
            if start < 0 or start >= size:
                continue
            if end >= size:
                end = size - 1
            if start > end:
                continue
            results.append((start, end))

    if not results:
        return None

    return results
```

