def unified_diff(a, b, context=3):
    if a == b:
        return []

    n, m = len(a), len(b)

    # LCS DP table
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # Backtrack to produce ordered diff operations
    ops = []
    i, j = n, m
    while i > 0 or j > 0:
        if i > 0 and j > 0 and a[i - 1] == b[j - 1]:
            ops.append(('equal', i - 1, j - 1))
            i -= 1
            j -= 1
        elif j > 0 and (i == 0 or dp[i][j - 1] >= dp[i - 1][j]):
            ops.append(('insert', j - 1))
            j -= 1
        else:
            ops.append(('delete', i - 1))
            i -= 1
    ops.reverse()

    # Annotate each op with its (a_pos, b_pos) at that point
    annotated = []
    ai, bi = 0, 0
    for op in ops:
        if op[0] == 'equal':
            annotated.append(('equal', ai, bi))
            ai += 1
            bi += 1
        elif op[0] == 'delete':
            annotated.append(('delete', ai, bi))
            ai += 1
        else:
            annotated.append(('insert', ai, bi))
            bi += 1

    # Identify maximal runs of non-equal ops (change regions)
    change_regions = []
    idx = 0
    while idx < len(annotated):
        if annotated[idx][0] != 'equal':
            start = idx
            while idx < len(annotated) and annotated[idx][0] != 'equal':
                idx += 1
            change_regions.append((start, idx - 1))
        else:
            idx += 1

    if not change_regions:
        return []

    # Expand each change region by up to `context` equal lines on each side
    hunk_ranges = []
    for start, end in change_regions:
        h_start = start
        remaining = context
        pos = start - 1
        while pos >= 0 and remaining > 0 and annotated[pos][0] == 'equal':
            h_start = pos
            remaining -= 1
            pos -= 1

        h_end = end
        remaining = context
        pos = end + 1
        while pos < len(annotated) and remaining > 0 and annotated[pos][0] == 'equal':
            h_end = pos
            remaining -= 1
            pos += 1

        hunk_ranges.append((h_start, h_end))

    # Merge overlapping or touching hunks
    merged = []
    for hr in hunk_ranges:
        if merged and hr[0] <= merged[-1][1]:
            merged[-1] = (merged[-1][0], max(merged[-1][1], hr[1]))
        else:
            merged.append(hr)

    # Emit output
    result = []
    for h_start, h_end in merged:
        a_start = annotated[h_start][1]
        b_start = annotated[h_start][2]
        a_end = a_start
        b_end = b_start
        for idx in range(h_start, h_end + 1):
            tag, ap, bp = annotated[idx]
            if tag == 'equal':
                a_end = ap + 1
                b_end = bp + 1
            elif tag == 'delete':
                a_end = ap + 1
            else:
                b_end = bp + 1

        a_len = a_end - a_start
        b_len = b_end - b_start

        result.append(f"@@ -{a_start + 1},{a_len} +{b_start + 1},{b_len} @@")

        for idx in range(h_start, h_end + 1):
            tag, ap, bp = annotated[idx]
            if tag == 'equal':
                result.append(f" {a[ap]}")
            elif tag == 'delete':
                result.append(f"-{a[ap]}")
            else:
                result.append(f"+{b[bp]}")

    return result
