from collections import OrderedDict


class LFUCache:

    def __init__(self, capacity):
        self.capacity = capacity
        self.key_to_val_freq = {}
        self.freq_to_keys = {}
        self.min_freq = 0

    def get(self, key):
        if key not in self.key_to_val_freq:
            return -1
        value, freq = self.key_to_val_freq[key]
        self._bump(key, freq)
        return value

    def put(self, key, value):
        if self.capacity == 0:
            return
        if key in self.key_to_val_freq:
            self.key_to_val_freq[key] = (value, self.key_to_val_freq[key][1])
            self._bump(key, self.key_to_val_freq[key][1])
        else:
            if len(self.key_to_val_freq) >= self.capacity:
                lru = self.freq_to_keys[self.min_freq]
                evict_key, _ = lru.popitem(last=False)
                del self.key_to_val_freq[evict_key]
                if not lru:
                    del self.freq_to_keys[self.min_freq]
            self.key_to_val_freq[key] = (value, 1)
            if 1 not in self.freq_to_keys:
                self.freq_to_keys[1] = OrderedDict()
            self.freq_to_keys[1][key] = None
            self.min_freq = 1

    def _bump(self, key, freq):
        self.freq_to_keys[freq].pop(key)
        if not self.freq_to_keys[freq]:
            del self.freq_to_keys[freq]
            if self.min_freq == freq:
                self.min_freq += 1
        new_freq = freq + 1
        self.key_to_val_freq[key] = (self.key_to_val_freq[key][0], new_freq)
        if new_freq not in self.freq_to_keys:
            self.freq_to_keys[new_freq] = OrderedDict()
        self.freq_to_keys[new_freq][key] = None
