import heapq

def topk(stream, k):
    heap = []
    for i, (value, label) in enumerate(stream):
        item = (value, -i, label)
        if len(heap) < k:
            heapq.heappush(heap, item)
        elif value > heap[0][0]:
            heapq.heapreplace(heap, item)
    result = sorted(heap, key=lambda x: (-x[0], -x[1]))
    return [(x[0], x[2]) for x in result]
