from collections import defaultdict

def window_medians(a, k):
    n = len(a)
    if k <= 0 or k > n:
        return []

    max_heap = []  # lower half (negated for max-heap behavior)
    min_heap = []  # upper half
    delayed = defaultdict(int)
    max_size = 0
    min_size = 0

    def prune(heap, is_max):
        while heap:
            val = -heap[0] if is_max else heap[0]
            if delayed[val] > 0:
                delayed[val] -= 1
                heapq.heappop(heap)
            else:
                break

    def balance():
        nonlocal max_size, min_size
        while max_size > min_size + 1:
            val = -heapq.heappop(max_heap)
            heapq.heappush(min_heap, val)
            max_size -= 1
            min_size += 1
            prune(max_heap, True)
        while min_size > max_size:
            val = heapq.heappop(min_heap)
            heapq.heappush(max_heap, -val)
            min_size -= 1
            max_size += 1
            prune(min_heap, False)

    def add(num):
        nonlocal max_size, min_size
        if not max_heap or num <= -max_heap[0]:
            heapq.heappush(max_heap, -num)
            max_size += 1
        else:
            heapq.heappush(min_heap, num)
            min_size += 1
        balance()

    def remove(num):
        nonlocal max_size, min_size
        delayed[num] += 1
        if max_heap and num <= -max_heap[0]:
            max_size -= 1
        else:
            min_size -= 1
        if max_heap and num == -max_heap[0]:
            prune(max_heap, True)
        if min_heap and num == min_heap[0]:
            prune(min_heap, False)
        balance()

    def get_median():
        if k % 2 == 1:
            return float(-max_heap[0])
        else:
            return (-max_heap[0] + min_heap[0]) / 2.0

    result = []
    for i in range(n):
        add(a[i])
        if i >= k:
            remove(a[i - k])
        if i >= k - 1:
            result.append(get_median())

