    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n
        self.history = []
        self.num_components = n

    def find(self, x):
        while self.parent[x] != x:
            x = self.parent[x]
        return x

    def union(self, a, b):
        ra = self.find(a)
        rb = self.find(b)
        if ra == rb:
            return False
        if self.size[ra] > self.size[rb]:
            ra, rb = rb, ra
        self.history.append((ra, rb, self.size[rb]))
        self.parent[ra] = rb
        self.size[rb] += self.size[ra]
        self.num_components -= 1
        return True

    def snapshot(self):
        return len(self.history)

    def rollback(self, token):
        while len(self.history) > token:
            ra, rb, old_size_rb = self.history.pop()
            self.parent[ra] = ra
            self.size[rb] = old_size_rb
            self.num_components += 1

    def components(self):
        return self.num_components
