def to_base(n, alphabet):
    base = len(alphabet)
    if n == 0:
        return alphabet[0]
    negative = n < 0
    n = abs(n)
    digits = []
    while n > 0:
        n, remainder = divmod(n, base)
        digits.append(alphabet[remainder])
    if negative:
        digits.append('-')
    return ''.join(reversed(digits))


def from_base(s, alphabet):
    if not s:
        raise ValueError("empty string")
    negative = False
    if s[0] == '-':
        negative = True
        s = s[1:]
        if not s:
            raise ValueError("empty string")
    base = len(alphabet)
    value = 0
    for ch in s:
        idx = alphabet.find(ch)
        if idx == -1:
            raise ValueError(f"character '{ch}' not in alphabet")
        value = value * base + idx
    return -value if negative else value
