def merge_sorted(iterables):
    import heapq

    heap = []
    for i, it in enumerate(iterables):
        it = iter(it)
        try:
            val = next(it)
        except StopIteration:
            continue
        heap.append((val, i, it))

    heapq.heapify(heap)

    while heap:
        val, i, it = heapq.heappop(heap)
        yield val
        try:
            next_val = next(it)
        except StopIteration:
            continue
        heapq.heappush(heap, (next_val, i, it))
