import heapq

def shortest_path(graph, src, dst):
    if src == dst:
        return (0, [src])

    heap = [(0, 0, (src,))]
    visited = set()

    while heap:
        cost, edges, path = heapq.heappop(heap)
        node = path[-1]

        if node in visited:
            continue

        if node == dst:
            return (cost, list(path))

        visited.add(node)

        for neighbour, weight in graph.get(node, []):
            if neighbour not in visited:
                new_cost = cost + weight
                new_edges = edges + 1
                new_path = path + (neighbour,)
                heapq.heappush(heap, (new_cost, new_edges, new_path))

    return (None, [])
