function pLimit(n) {
  let active = 0;
  const queue = [];

  function next() {
    if (queue.length === 0 || active >= n) return;
    active++;
    const { fn, resolve, reject } = queue.shift();
    fn().then(
      (val) => {
        active--;
        resolve(val);
        next();
      },
      (err) => {
        active--;
        reject(err);
        next();
      }
    );
  }

  return function (fn) {
    return new Promise((resolve, reject) => {
      queue.push({ fn, resolve, reject });
      next();
    });
  };
}

module.exports = pLimit;
