const toposortTasks = (tasks) => {
  return new Promise((resolve, reject) => {
    const names = Object.keys(tasks);

    for (const name of names) {
      for (const dep of tasks[name].deps) {
        if (!(dep in tasks)) {
          reject(new Error(`Unknown dependency: ${dep}`));
          return;
        }
      }
    }

    const inDegree = {};
    const dependents = {};
    for (const name of names) {
      inDegree[name] = tasks[name].deps.length;
      dependents[name] = [];
    }
    for (const name of names) {
      for (const dep of tasks[name].deps) {
        dependents[dep].push(name);
      }
    }

    const tempIn = { ...inDegree };
    const tempQ = names.filter(n => tempIn[n] === 0);
    let visited = 0;
    while (tempQ.length) {
      const node = tempQ.shift();
      visited++;
      for (const d of dependents[node]) {
        tempIn[d]--;
        if (tempIn[d] === 0) tempQ.push(d);
      }
    }
    if (visited < names.length) {
      reject(new Error('cycle detected'));
      return;
    }

    if (names.length === 0) { resolve({}); return; }

    const results = {};
    const failed = new Set();
    let firstError = null;
    let remaining = names.length;
    let running = 0;

    const markFailed = (name) => {
      for (const dep of dependents[name]) {
        if (!failed.has(dep)) {
          failed.add(dep);
          remaining--;
          markFailed(dep);
        }
      }
    };

    const checkDone = () => {
      if (remaining === 0 && running === 0) {
        if (firstError) reject(firstError);
        else resolve(results);
      }
    };

    const tryRun = (name) => {
      const task = tasks[name];
      const depValues = {};
      for (const dep of task.deps) {
        depValues[dep] = results[dep];
      }
      running++;
      task.run(depValues).then(value => {
        results[name] = value;
        running--;
        remaining--;
        for (const dep of dependents[name]) {
          if (failed.has(dep)) continue;
          inDegree[dep]--;
          if (inDegree[dep] === 0) {
            tryRun(dep);
          }
        }
        checkDone();
      }).catch(err => {
        running--;
        remaining--;
        if (!firstError) firstError = err;
        failed.add(name);
        markFailed(name);
        checkDone();
      });
    };

    for (const name of names) {
      if (inDegree[name] === 0) {
        tryRun(name);
      }
    }
  });
};

