export class Bus<E extends Record<string, unknown>> {
  private readonly handlers = new Map<keyof E, Set<(payload: any) => void>>();

  on<K extends keyof E>(k: K, fn: (payload: E[K]) => void): () => void {
    let set = this.handlers.get(k);
    if (!set) {
      set = new Set();
      this.handlers.set(k, set);
    }
    const handler = fn as (payload: any) => void;
    set.add(handler);
    return () => {
      set!.delete(handler);
    };
  }

  emit<K extends keyof E>(
    k: K,
    ...args: E[K] extends void ? [] : [payload: E[K]]
  ): void {
    const set = this.handlers.get(k);
    if (set) {
      for (const fn of set) {
        fn(args[0]);
      }
    }
  }
}
