export type Ok<T> = { readonly tag: "ok"; readonly value: T };
export type Err<E> = { readonly tag: "err"; readonly error: E };
export type Result<T, E> = Ok<T> | Err<E>;

export function ok<T>(value: T): Ok<T> {
  return { tag: "ok", value };
}

export function err<E>(error: E): Err<E> {
  return { tag: "err", error };
}

export function isOk<T, E>(r: Result<T, E>): r is Ok<T> {
  return r.tag === "ok";
}

export function isErr<T, E>(r: Result<T, E>): r is Err<E> {
  return r.tag === "err";
}

export function map<T, E, U>(r: Result<T, E>, fn: (value: T) => U): Result<U, E> {
  if (r.tag === "ok") {
    return { tag: "ok", value: fn(r.value) };
  }
  return { tag: "err", error: r.error };
}

export function unwrapOr<T, E>(r: Result<T, E>, fallback: T): T {
  if (r.tag === "ok") {
    return r.value;
  }
  return fallback;
}
