type ExtractParams<T extends string> =
  T extends `${string}:${infer Param}/${infer Rest}`
    ? Param | ExtractParams<Rest>
    : T extends `${string}:${infer Param}`
      ? Param
      : never;

type RouteFunction<T extends string> =
  [ExtractParams<T>] extends [never]
    ? () => string
    : (params: { [K in ExtractParams<T>]: string }) => string;

type RouteMap<T extends Record<string, string>> = {
  [K in keyof T]: RouteFunction<T[K]>;
};

function escapeRegExp(s: string): string {
  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function extractParamNames(template: string): string[] {
  const matches = template.match(/:([a-zA-Z_][a-zA-Z0-9_]*)/g);
  if (!matches) return [];
  return [...new Set(matches.map((m) => m.slice(1)))];
}

export function defineRoutes<T extends Record<string, string>>(
  routes: T
): RouteMap<T> {
  const result = {} as RouteMap<T>;
  for (const key of Object.keys(routes) as (keyof T & string)[]) {
    const template = routes[key];
    const paramNames = extractParamNames(template);
    if (paramNames.length === 0) {
      (result as Record<string, unknown>)[key] = (): string => template;
    } else {
      (result as Record<string, unknown>)[key] = (
        params: Record<string, string>
      ): string => {
        let path = template;
        for (const name of paramNames) {
          path = path.replace(
            new RegExp(":" + escapeRegExp(name) + "(?=[/]|$)", "g"),
            params[name]
          );
        }
        return path;
      };
    }
  }
  return result;
}
