export type DeepPartial<T> = T extends Function
  ? T
  : T extends Array<infer U>
  ? Array<U>
  : T extends object
  ? { [K in keyof T]?: DeepPartial<T[K]> }
  : T;

export function applyPatch<T>(base: T, patch: DeepPartial<T>): T {
  if (patch === undefined) return base;
  if (patch === null) return patch as unknown as T;
  if (typeof patch !== "object" || Array.isArray(patch)) {
    return patch as unknown as T;
  }

  const baseObj: Record<string, unknown> =
    base !== undefined &&
    base !== null &&
    typeof base === "object" &&
    !Array.isArray(base)
      ? { ...(base as unknown as Record<string, unknown>) }
      : {};

  const patchObj = patch as unknown as Record<string, unknown>;
  const result: Record<string, unknown> = { ...baseObj };

  for (const key of Object.keys(patchObj)) {
    const patchVal: unknown = patchObj[key];
    if (patchVal === undefined) continue;
    result[key] = applyPatch<unknown>(
      baseObj[key],
      patchVal as DeepPartial<unknown>
    );
  }

  return result as unknown as T;
}
